/**
 * @description
 */

let freeTimes = [3, 5, 10, 15];
let reels = [3, 4, 5, 6];

cc.Class({
    extends: cc.Component,
    properties: {
        _successCallback: null,
        _canSelect: false,
        _extraFreeInfo: null,
        _updateFreeTimes: false,
        _updateReels: false,
        _timesTimer: 0,
        _reelsTimer: 0,
        _timesCount: 0,
        _reelsCount: 0,
        _timesInterval: 0.1,
        _reelsInterval: 0.1,
    },

    onLoad() {
        for (let i = 1; i < 6; i++) {
            let node = cc.find("node_" + i, this.node);
            node.on(cc.Node.EventType.TOUCH_END, async ()=>{
                if (!this._canSelect) {
                    return;
                }
                cc.find("node_5", this.node).stopAllActions();
                this._canSelect = false;
                let req = {rtype:1, choiceId: i};
                let result = await cc.vv.gameData.reqSubGame(req);
                if (result.code === 200) {
                    this._extraFreeInfo = result.data.extraFreeInfo;
                    cc.vv.gameData.SetFreeTime(this._extraFreeInfo.options[result.data.choiceId - 1].freeCnt);
                    cc.vv.gameData.SetTotalFree(this._extraFreeInfo.options[result.data.choiceId - 1].freeCnt);

                    for (let j = 1; j < 6; j++) {
                        if (result.data.choiceId !== j) {
                            cc.find("node_" + j + "/black", this.node).active = true;
                        }
                    }

                    if (result.data.choiceId === 5) {
                        Global.SlotsSoundMgr.playEffect("sound_AZTEC_click_random");
                        let node = cc.find("node_" + result.data.choiceId, this.node);
                        cc.tween(node)
                            .to(0.2, {scale: 0.8})
                            .call(()=>{
                                let baozha = cc.find("baozha", node);
                                this.playAnimationOnce(baozha);

                                let light = cc.find("light", node);
                                light.active = true;
                            })
                            .to(0.5, {scale: 1}, {easing: "backOut"})
                            .call(()=>{
                                Global.SlotsSoundMgr.playEffect("sound_AZTEC_click_run");
                                this._timesTimer = 0;
                                this._reelsTimer = 0;
                                this._updateFreeTimes = true;
                                this._updateReels = true;
                                cc.find("node_5/unselect", this.node).active = false;
                                cc.find("node_5/select", this.node).active = true;
                                cc.find("node_5/select/times_guang", this.node).active = false;
                                cc.find("node_5/select/reels_guang", this.node).active = false;
                            })
                            .start();
                    } else {
                        Global.SlotsSoundMgr.playEffect("sound_AZTEC_click");
                        let node = cc.find("node_" + result.data.choiceId, this.node);
                        cc.tween(node)
                            .to(0.2, {scale: 0.8})
                            .call(()=>{
                                let baozha = cc.find("baozha", node);
                                this.playAnimationOnce(baozha);

                                let light = cc.find("light", node);
                                light.active = true;
                            })
                            .to(0.5, {scale: 1}, {easing: "backOut"})
                            .start();

                        this.exitGame();
                    }
                }
            });
        }
    },

    getExtraFreeInfo() {
        return this._extraFreeInfo;
    },

    playAnimationOnce(node, animationName, callback) {
        node.active = true;
        if (animationName) {
            node.getComponent(cc.Animation).play(animationName);
        } else {
            node.getComponent(cc.Animation).play();
        }

        node.getComponent(cc.Animation).on("stop", ()=>{
            node.getComponent(cc.Animation).off("stop");
            node.active = false;
            if (callback) {
                callback();
            }
        });
    },

    startGame(success) {
        Global.SlotsSoundMgr.playEffect("sound_AZTEC_fs_choose_window");
        let free_dialog = this.node.parent;
        free_dialog.active = true;
        let free_bg = free_dialog.getChildByName("free_bg");
        free_bg.opacity = 200;
        this.node.active = true;
        this.node.opacity = 255;
        this.reset();
        this._successCallback = success;
        this._canSelect = true;

        if (cc.vv.gameData.isNeedAutoPlay()) {
            let node = cc.find("node_5", this.node);
            node.stopAllActions();
            cc.tween(node)
                .delay(cc.vv.gameData.getManualAutoPlayTime())
                .call(async ()=>{
                    if (!this._canSelect) {
                        return;
                    }
                    this._canSelect = false;
                    let req = {rtype:1, choiceId: 5};
                    let result = await cc.vv.gameData.reqSubGame(req);
                    if (result.code === 200) {
                        this._extraFreeInfo = result.data.extraFreeInfo;
                        cc.vv.gameData.SetFreeTime(this._extraFreeInfo.options[result.data.choiceId - 1].freeCnt);
                        cc.vv.gameData.SetTotalFree(this._extraFreeInfo.options[result.data.choiceId - 1].freeCnt);

                        for (let j = 1; j < 6; j++) {
                            if (result.data.choiceId !== j) {
                                cc.find("node_" + j + "/black", this.node).active = true;
                            }
                        }

                        if (result.data.choiceId === 5) {
                            Global.SlotsSoundMgr.playEffect("sound_AZTEC_click_random");
                            let node = cc.find("node_" + result.data.choiceId, this.node);
                            cc.tween(node)
                                .to(0.2, {scale: 0.8})
                                .call(()=>{
                                    let baozha = cc.find("baozha", node);
                                    this.playAnimationOnce(baozha);

                                    let light = cc.find("light", node);
                                    light.active = true;
                                })
                                .to(0.5, {scale: 1}, {easing: "backOut"})
                                .call(()=>{
                                    Global.SlotsSoundMgr.playEffect("sound_AZTEC_click_run");
                                    this._timesTimer = 0;
                                    this._reelsTimer = 0;
                                    this._updateFreeTimes = true;
                                    this._updateReels = true;
                                    cc.find("node_5/unselect", this.node).active = false;
                                    cc.find("node_5/select", this.node).active = true;
                                    cc.find("node_5/select/times_guang", this.node).active = false;
                                    cc.find("node_5/select/reels_guang", this.node).active = false;
                                })
                                .start();
                        } else {
                            Global.SlotsSoundMgr.playEffect("sound_AZTEC_click");
                            let node = cc.find("node_" + result.data.choiceId, this.node);
                            cc.tween(node)
                                .to(0.2, {scale: 0.8})
                                .call(()=>{
                                    let baozha = cc.find("baozha", node);
                                    this.playAnimationOnce(baozha);

                                    let light = cc.find("light", node);
                                    light.active = true;
                                })
                                .to(0.5, {scale: 1}, {easing: "backOut"})
                                .start();

                            this.exitGame();
                        }
                    }
                })
                .start();
        }
    },

    exitGame() {
        cc.tween(this.node)
            .delay(1.7)
            .call(()=>{
                if (this._successCallback) {
                    this._successCallback();
                    this._successCallback = null;
                }
                let free_dialog = this.node.parent;
                free_dialog.active = true;
                let free_bg = free_dialog.getChildByName("free_bg");
                cc.tween(free_bg)
                    .to(0.3, {opacity: 0})
                    .start();
            })
            .to(0.3, {opacity: 0})
            .call(()=>{
                this.node.active = false;
            })
            .start();
    },

    reset() {
        // 重置所有节点
        for (let i = 1; i < 6; i++) {
            let node = cc.find("node_" + i, this.node);
            node.getChildByName("baozha").active = false;
            node.getChildByName("light").active = false;
            node.getChildByName("black").active = false;
        }

        let node = cc.find("node_5", this.node);
        node.getChildByName("unselect").active = true;
        node.getChildByName("select").active = false;

        // 重置变量
        this._successCallback = null;
        this._canSelect = false;
        this._extraFreeInfo = null;

        this._updateFreeTimes = false;
        this._updateReels = false;
        this._timesTimer = 0;
        this._reelsTimer = 0;
        this._timesCount = 0;
        this._reelsCount = 0;
        this._timesInterval = 0.1;
        this._reelsInterval = 0.1;
    },

    update(dt) {
        if (this._updateFreeTimes) {
            this._timesTimer += dt;
            if (this._timesTimer >= this._timesInterval) {
                this._timesTimer = 0;
                this._timesCount++;
                if (this._timesInterval >= 0.5) {
                    cc.find("node_5/select/times", this.node).getComponent(cc.Label).string = this._extraFreeInfo.options[4].freeCnt;
                    this._timesCount = 0;
                    this._updateFreeTimes = false;
                    this._timesInterval = 0.1;
                    let guang = cc.find("node_5/select/times_guang", this.node);
                    guang.active = true;
                    guang.scale = 0;
                    cc.tween(guang)
                        .to(0.5, {scale: 2})
                        .delay(0.5)
                        .call(()=>{
                            guang.active = false;
                        })
                        .start();
                    // cc.tween(this.node)
                    //     .delay(0.5)
                    //     .call(()=>{
                    //         this._updateReels = true;
                    //     })
                    //     .start();
                } else {
                    cc.find("node_5/select/times", this.node).getComponent(cc.Label).string = freeTimes[Math.floor(Math.random() * 4)];
                }
            }
            if (this._timesCount >= 10) {
                this._timesInterval += 0.1;
                if (this._timesInterval >= 0.5) {
                    this._timesInterval = 0.5;
                }
            }
        }

        if (this._updateReels) {
            this._reelsTimer += dt;
            if (this._reelsTimer >= this._reelsInterval) {
                this._reelsTimer = 0;
                this._reelsCount++;
                if (this._reelsInterval >= 0.5) {
                    cc.find("node_5/select/reels", this.node).getComponent(cc.Label).string = this._extraFreeInfo.options[4].rowCnt + "X5";
                    this._reelsCount = 0;
                    this._updateReels = false;
                    this._reelsInterval = 0.1;
                    let guang = cc.find("node_5/select/reels_guang", this.node);
                    guang.active = true;
                    guang.scale = 0;
                    cc.tween(guang)
                        .to(0.5, {scale: 2})
                        .delay(0.5)
                        .call(()=>{
                            guang.active = false;
                        })
                        .start();

                    cc.tween(this.node)
                        .delay(0.5)
                        .call(()=>{
                            this.exitGame();
                        })
                        .start();
                    Global.SlotsSoundMgr.playEffect("sound_AZTEC_click_over");
                } else {
                    cc.find("node_5/select/reels", this.node).getComponent(cc.Label).string = reels[Math.floor(Math.random() * 4)] + "X5";
                }
            }
            if (this._reelsCount >= 55) {
                this._reelsInterval += 0.1;
                if (this._reelsInterval >= 0.5) {
                    this._reelsInterval = 0.5;
                }
            }
        }
    },
});