cc.Class({
    extends: require("LMSlots_Logic_Base"),

    properties: {},

    // LIFE-CYCLE CALLBACKS:

    onLoad() {
        this._super();

        let jackpotGameScript = cc.find("safe_node/select_jackpot_game", this.node).getComponent("RisingSunTheGreatKing_SelectJackpotGame");
        cc.vv.gameData.GetSlotsScript().setJackpotGameScript(jackpotGameScript);

        let selectFreeTimesScript = cc.find("safe_node/free_dialog/enter_node", this.node).getComponent("RisingSunTheGreatKing_SelectFreeTimes");
        cc.vv.gameData.GetSlotsScript().setSelectFreeTimesScript(selectFreeTimesScript);

        // cc.vv.gameData.GetSlotsScript().setSelectSymbolScript(selectSymbolScript);

        Global.registerEvent(cc.vv.gameData._EventId.SLOT_TOTALBET_UPDATED, this.onUpdateBet, this);
    },

    StartSlot:function(){
        this._super();

        let deskInfo = cc.vv.gameData.getDeskInfo();
        let selectSymbolScript = cc.find("safe_node/select_symbol", this.node).getComponent("RisingSunTheGreatKing_SelectStartSymbol");
        if (!deskInfo.extraFreeInfo && !deskInfo.jackpotGame) {
            if (deskInfo.mults.length >= deskInfo.betLevelConfig[deskInfo.betLevelConfig.length - 1]) {
                selectSymbolScript.init();
            }
        }
    },

    onUpdateBet: function () {
        let deskInfo = cc.vv.gameData.getDeskInfo();
        cc.vv.gameData.GetSlotsScript().updateActiveGoldSymbol(deskInfo.currmult);
    },

    // update (dt) {},
});