/**
 * @description
 */

cc.Class({
    extends: require("LMSlots_Slots_Base"),
    properties: {
        _curCoinInBowlIndex: 0,
        _jackpotGameScript: null,
        _selectFreeTimesScript: null,


        _playBowlLight: true,
        _bowlLightTimer: 10,
    },

    //初始化
    Init:function(){
        this._super();

        Global.SlotsSoundMgr.playEffect("sound_AZTEC_enter_game");

        let deskInfo = cc.vv.gameData.getDeskInfo();

        let btn_tips = cc.find("reels_frame/symbol_info/btn_tips", this.node);
        btn_tips.on("click", ()=>{
            if (cc.vv.gameData.GetSlotState() !== "idle") {
                return;
            }
            if (cc.vv.gameData.GetTotalFree() > 0) {
                return;
            }

            if (deskInfo.mults.length < deskInfo.betLevelConfig[deskInfo.betLevelConfig.length - 1]) {
                return;
            }

            this._bottomScript.ShowBtnsByState("moveing_1");
            cc.find("select_symbol", this.node.parent).getComponent("RisingSunTheGreatKing_SelectStartSymbol").init();
        });
    },

    //重写
    StartMove: function () {
        this._super();

        Global.SlotsSoundMgr.playNormalBgm();
    },

    async ReconnectShow(){
        //是否是免费游戏
        let deskInfo = cc.vv.gameData.getDeskInfo();
        if (deskInfo.jackpotGame) {
            this._bottomScript.ShowBtnsByState("unstoped");
            this.reconnectSelectJackpotGame();
        }

        if (deskInfo.extraFreeInfo) {
            if (deskInfo.extraFreeInfo.state === 0) {
                this._bottomScript.ShowBtnsByState("moveing_1");
                await this.enterSelectFreeTimes();

                this.ShowGameview(true);
                let extraFreeInfo = this._selectFreeTimesScript.getExtraFreeInfo();
                if (extraFreeInfo.rowCnt > this._cfg.row) {
                    for (let reel of this._reels) {
                        reel.AddCount(extraFreeInfo.rowCnt - this._cfg.row, 0.01);
                    }
                    await cc.vv.gameData.awaitTime(0.1);

                    cc.find("dechuanjiakang", this.node.parent).active = false;
                    // cc.find("jinzita", this.node.parent).scale = 1;
                }

                await cc.vv.gameData.awaitTime(0.5);

                await this.popFreeDialog(false);

                await cc.vv.gameData.awaitTime(0.5);

                // cc.vv.AudioManager.playBgm("games/BrilliantTreasures/", "free_bgm", true);
                Global.SlotsSoundMgr.stopBgm();
                Global.SlotsSoundMgr.playBgm("music_AZTEC_fs_bgm");

                this.CanDoNextRound();
            } else if (deskInfo.extraFreeInfo.state === 1) {
                this._bottomScript.ShowBtnsByState("moveing_1");
                if (deskInfo.extraFreeInfo.rowCnt > this._cfg.row) {
                    for (let reel of this._reels) {
                        reel.AddCount(deskInfo.extraFreeInfo.rowCnt - this._cfg.row, 0.01);
                    }
                    await cc.vv.gameData.awaitTime(0.5);

                    // cc.find("jinzita", this.node.parent).scale = 1;
                    cc.find("dechuanjiakang", this.node.parent).active = false;
                }

                this.ShowGameview(true);

                this.CanDoNextRound();
            }
        }

    },

    ShowGameview:function(bFree){
        this._super(bFree);

        // cc.find("AZTEC_bg5", this.node.parent).active = !bFree;
        // cc.find("AZTEC_bg2", this.node.parent).active = bFree;
    },

    ShowWinTrace:function(){
        let allWinIdx = []

        //中奖位置
        for(let i = 0; i < this._gameInfo.zjLuXian.length; i++){
            let item = this._gameInfo.zjLuXian[i]
            for(let idx = 0; idx < item.indexs.length; idx++){
                allWinIdx[item.indexs[idx]] = 1
            }
        }

        if(this._gameInfo.scatterZJLuXian && this._gameInfo.scatterZJLuXian.indexs){
            for(let i = 0; i < this._gameInfo.scatterZJLuXian.indexs.length; i++){
                let val = this._gameInfo.scatterZJLuXian.indexs[i]
                allWinIdx[val] = 1
            }
        }

        //总
        for (const key in allWinIdx) {
            let symbol = this.GetSymbolByIdx(Number(key))
            if(symbol){
                symbol.playWinAnimation()
                symbol.ShowKuang()
            }
        }
    },

    //根据服务端序号获取本地的symbol
    GetSymbolByIdx: function (idx) {
        let col = (idx - 1) % this._col
        let row = this._gameInfo.resultCards.length / this._cfg.col - Math.floor((idx - 1) / this._col) - 1
        return this._reels[col].GetSymbolByRow(row)
    },

    async OnSpinEnd() {
        this.ShowWinTrace();

        this.playCoinFlyAnimation();

        let winCoin = cc.vv.gameData.GetGameWin();
        let totalWinCoin = cc.vv.gameData.GetGameWin();
        if (cc.vv.gameData.GetTotalFree() > 0 && cc.vv.gameData.GetTotalFree() !== cc.vv.gameData.GetFreeTime()) {
            // 免费中
            totalWinCoin = cc.vv.gameData.GetGameTotalFreeWin();
        }

        this.ShowBottomWin(winCoin, totalWinCoin, true, async ()=>{
            if (this._gameInfo && this._gameInfo.jackpotGame) {
                // 触发jackpot game
                await this.triggerJackpotGame();
            }

            if (this.CheckEnterFreeGame()) {
                this.triggerFreeGame();
            } else {
                if (this.CheckExitFreeGame()) {
                    this.triggerExitFreeGame();
                } else {
                    let haveWild = false;
                    for (let i = 0; i < this._gameInfo.resultCards.length; i++) {
                        let resultCard = this._gameInfo.resultCards[i];
                        if (resultCard === this._cfg.wildId) {
                            haveWild = true;
                            break;
                        }
                    }

                    if (haveWild) {
                        await cc.vv.gameData.awaitTime(1);
                    } else {
                        // await cc.vv.gameData.awaitTime(0.1);
                    }

                    this.CanDoNextRound();
                }
            }
        });
    },

    //检查进入免费
    CheckEnterFreeGame:function(){
        return !!(this._gameInfo.extraFreeInfo && this._gameInfo.extraFreeInfo.state === 0);
    },

    CheckExtraFreeGame() {
        return !!(this._gameInfo.freeResult && this._gameInfo.freeResult.freeInfo && this._gameInfo.freeResult.freeInfo.freeCnt > 0);
    },

    CheckExitFreeGame() {
        return cc.vv.gameData.GetTotalFree() > 0 && cc.vv.gameData.GetFreeTime() === 0;
    },

    async triggerFreeGame() {
        this._bottomScript.ShowBtnsByState("moveing_1");

        Global.SlotsSoundMgr.playEffect("sound_AZTEC_wild_scatter_trigger");

        // 触发免费游戏
        await cc.vv.gameData.awaitTime(1);

        this.cutScenes();

        await cc.vv.gameData.awaitTime(1);

        await this.enterSelectFreeTimes();

        this.ShowGameview(true);
        let extraFreeInfo = this._selectFreeTimesScript.getExtraFreeInfo();
        if (extraFreeInfo.rowCnt > this._cfg.row) {
            for (let reel of this._reels) {
                reel.AddCount(extraFreeInfo.rowCnt - this._cfg.row, 0.01);
            }
            await cc.vv.gameData.awaitTime(0.1);

            // cc.find("jinzita", this.node.parent).scale = 1;
            cc.find("dechuanjiakang", this.node.parent).active = false;
        }

        await cc.vv.gameData.awaitTime(0.5);

        await this.popFreeDialog(false);

        await cc.vv.gameData.awaitTime(0.5);

        // cc.vv.AudioManager.playBgm("games/BrilliantTreasures/", "free_bgm", true);
        Global.SlotsSoundMgr.stopBgm();
        Global.SlotsSoundMgr.playBgm("music_AZTEC_fs_bgm");

        this.CanDoNextRound();
    },

    async triggerExitFreeGame() {
        this._bottomScript.ShowBtnsByState("moveing_1");

        await cc.vv.gameData.awaitTime(1);

        await this.popFreeResultDialog();

        this.cutScenes();

        await cc.vv.gameData.awaitTime(1);

        // cc.find("jinzita", this.node.parent).scale = 1.45;
        cc.find("dechuanjiakang", this.node.parent).active = true;

        for (let reel of this._reels) {
            reel.StartRecycleSymbol(0.01);
        }

        await cc.vv.gameData.awaitTime(0.02);

        for (let reel of this._reels) {
            reel.clearLastSymbol();
        }

        this.ShowGameview(false);

        await cc.vv.gameData.awaitTime(1);

        this.ShowBottomWin(cc.vv.gameData.GetGameTotalFreeWin(), cc.vv.gameData.GetGameTotalFreeWin(), true, () => {
            Global.SlotsSoundMgr.stopBgm();
            Global.SlotsSoundMgr.playNormalBgm();
            this.CanDoNextRound();
        });
    },

    popFreeResultDialog() {
        return new Promise(async (success) => {
            Global.SlotsSoundMgr.playEffect("sound_AZTEC_over_fs");
            let free_dialog = cc.find("free_dialog", this.node.parent);
            free_dialog.active = true;

            let free_bg = cc.find("free_bg", free_dialog);
            free_bg.opacity = 0;
            free_bg.runAction(cc.fadeTo(0.2, 200));

            let dialog = cc.find("result_node", free_dialog);
            dialog.active = true;

            cc.tween(dialog)
                .to(0.5, {scale: 1}, {easing: "backOut"})
                .start()

            let coin = cc.find("bg/coins", dialog);
            coin.getComponent(cc.Label).string = "";

            let times = cc.find("bg/times", dialog);
            times.getComponent(cc.Label).string = cc.vv.gameData.GetTotalFree();

            let btn_collect = cc.find("bg/btn_collect", dialog);
            Global.doRoallNumEff(coin, 0, cc.vv.gameData.GetGameTotalFreeWin(), 3, null, null, 0, true);

            await cc.vv.gameData.awaitTime(0.5);

            btn_collect.off("click");
            let func = async ()=>{
                btn_collect.off("click");
                cc.tween(free_bg)
                    .to(0.5, {opacity: 0})
                    .start();

                cc.tween(dialog)
                    .to(0.5, {scale: 0}, {easing: "backIn"})
                    .call(()=>{
                        dialog.active = false;
                        free_dialog.active = false;
                        success();
                    })
                    .start();
            }
            cc.vv.gameData.checkAutoPlay(btn_collect, func);
            btn_collect.on("click", async () => {
                btn_collect.stopAllActions();
                await func();
            });
        })
    },

    popFreeDialog() {
        return new Promise(async (success) => {
            Global.SlotsSoundMgr.playEffect("sound_AZTEC_enter_fs");
            let free_dialog = cc.find("free_dialog", this.node.parent);
            free_dialog.active = true;

            let free_bg = cc.find("free_bg", free_dialog);
            free_bg.opacity = 0;
            free_bg.runAction(cc.fadeTo(0.2, 200));

            let dialog = cc.find("free_node", free_dialog);
            dialog.active = true;
            dialog.opacity = 255;
            dialog.scale = 0;

            cc.tween(dialog)
                .to(0.5, {scale: 1}, {easing: "backOut"})
                .start();


                cc.find("bg/times", dialog).getComponent(cc.Label).string = cc.vv.gameData.GetTotalFree();
                let ways = {"3": 243, "4": 1024, "5": 3125, "6": 7776};
                let extraFreeInfo = this._selectFreeTimesScript.getExtraFreeInfo();
                cc.find("bg/ways", dialog).getComponent(cc.Label).string = ways[extraFreeInfo.rowCnt];

                let btn_start = cc.find("bg/btn_start", dialog);
                let func = ()=>{
                    btn_start.off("click");

                    cc.tween(dialog)
                        .to(0.5, {opacity: 0})
                        .call(()=>{
                            dialog.active = false;
                            free_dialog.active = false;
                            success();
                        })
                        .start();

                    cc.tween(free_bg)
                        .to(0.5, {opacity: 0})
                        .start();
                }
                cc.vv.gameData.checkAutoPlay(btn_start, func);
                btn_start.on("click", () => {
                    btn_start.stopAllActions();
                    func();
                });

        });
    },

    cutScenes() {
        let transition = cc.find("transition", this.node.parent);
        Global.SlotsSoundMgr.playEffect("sound_AZTEC_bg_guochang");
        if (transition) {
            transition.active = true;
            transition.getComponent(sp.Skeleton).setAnimation(0, "skill", false);
            transition.getComponent(sp.Skeleton).setCompleteListener(()=>{
                transition.getComponent(sp.Skeleton).setCompleteListener(null);
                transition.active = false;
            });
        }
    },

    playAnimationOnce(node, animationName, callback) {
        node.active = true;
        if (animationName) {
            node.getComponent(cc.Animation).play(animationName);
        } else {
            node.getComponent(cc.Animation).play();
        }

        node.getComponent(cc.Animation).on("stop", ()=>{
            node.getComponent(cc.Animation).off("stop");
            node.active = false;
            if (callback) {
                callback();
            }
        });
    },

    shake() {
        let safe_node = this.node.parent;
        for (let child of safe_node.children) {
            if (child.name !== "LMSlots_Top" && child.name !== "LMSlots_Bottom" && child.active) {
                let action = cc.shake(3, 15, 15);
                child.runAction(action);
            }
        }
    },

    async triggerJackpotGame() {
        return new Promise(async (suc)=>{
            this._bottomScript.ShowBtnsByState("moveing_1");

            Global.SlotsSoundMgr.playEffect("sound_AZTEC_bg_doudong");
            this.shake();

            await cc.vv.gameData.awaitTime(3);

            let spine = cc.find("dechuanjiakang", this.node.parent).getComponent(sp.Skeleton);
            spine.setAnimation(0, "skill", false);
            spine.addAnimation(0, "idle", true);
            // this.playAnimationOnce(cc.find("jinzita/collecttasg", this.node.parent));

            await cc.vv.gameData.awaitTime(1);

            this.cutScenes();

            await cc.vv.gameData.awaitTime(1);

            Global.SlotsSoundMgr.stopBgm();
            Global.SlotsSoundMgr.playBgm("music_AZTEC_bonus_game_bgm");
            await this.enterSelectJackpotGame();

            this.cutScenes();

            await cc.vv.gameData.awaitTime(1);

            this._jackpotGameScript.node.active = false;

            let winCoin = this._jackpotGameScript.getWinCoin();
            let totalWinCoin = cc.vv.gameData.GetGameWin() + winCoin;
            if (cc.vv.gameData.GetTotalFree() > 0 && cc.vv.gameData.GetTotalFree() !== cc.vv.gameData.GetFreeTime()) {
                totalWinCoin = cc.vv.gameData.GetGameTotalFreeWin() + winCoin;
            }
            this.ShowBottomWin(winCoin, totalWinCoin, true, async ()=>{
                Global.SlotsSoundMgr.stopBgm();
                Global.SlotsSoundMgr.playNormalBgm();

                if (suc) {
                    suc();
                }
            });
        });

    },

    async reconnectSelectJackpotGame() {
        let deskInfo = cc.vv.gameData.getDeskInfo();
        if (deskInfo.jackpotGame) {
            await new Promise((success)=>{
                this._jackpotGameScript.reconnect(deskInfo.jackpotGame, success);
            });
        }

        let winCoin = this._jackpotGameScript.getWinCoin();
        let totalWinCoin = deskInfo.winCoin ? deskInfo.winCoin : 0 + winCoin;
        if (cc.vv.gameData.GetTotalFree() > 0 && cc.vv.gameData.GetTotalFree() !== cc.vv.gameData.GetFreeTime()) {
            totalWinCoin = cc.vv.gameData.GetTotalFreeWin() + winCoin;
        }
        this.ShowBottomWin(winCoin, totalWinCoin, true, async ()=>{
            await cc.vv.gameData.awaitTime(3);

            this.cutScenes();

            await cc.vv.gameData.awaitTime(0.5);

            this._jackpotGameScript.exitGame();

            await cc.vv.gameData.awaitTime(1);

            Global.SlotsSoundMgr.playNormalBgm();

            this.CanDoNextRound();
        });
    },

    enterSelectJackpotGame() {
        return new Promise((success)=>{
            this._jackpotGameScript.startGame(success, this._gameInfo.jackpotGame);
        });
    },

    enterSelectFreeTimes() {
        return new Promise((success)=>{
            cc.find("free_dialog/enter_node", this.node.parent)
                .getComponent("RisingSunTheGreatKing_SelectFreeTimes").startGame(success);
        });
    },

    setJackpotGameScript(script) {
        this._jackpotGameScript = script;
    },

    setSelectFreeTimesScript(script) {
        this._selectFreeTimesScript = script;
    },

    async playCoinFlyAnimation() {
        let haveWild = false;
        for (let i = 0; i < this._gameInfo.resultCards.length; i++) {
            let resultCard = this._gameInfo.resultCards[i];
            if (resultCard === this._cfg.wildId) {
                haveWild = true;
                let symbol = this.GetSymbolByIdx(i + 1);
                if (symbol) {
                    // 飞金币
                    symbol.playBonusSgAnimation();

                    cc.tween(symbol)
                        .delay(0.5)
                        .call(()=>{
                            let endPos = cc.find("bowl", this.node).convertToWorldSpaceAR(cc.v2(0, 0));
                            endPos = this.node.parent.convertToNodeSpaceAR(endPos);
                            let startPos = symbol.node.convertToWorldSpaceAR(cc.v2(0, 0));
                            startPos = this.node.parent.convertToNodeSpaceAR(startPos);
                            let particle = cc.instantiate(cc.find("particle_fly", this.node.parent));
                            particle.active = true;
                            particle.parent = this.node.parent;
                            particle.position = startPos;

                            Global.SlotsSoundMgr.playEffect("sound_AZTEC_fire_fly");

                            cc.tween(particle)
                                .to(0.5, {position: endPos})
                                .removeSelf()
                                .start();
                        })
                        .start();
                }
            }
        }

        if (haveWild) {
            await cc.vv.gameData.awaitTime(1);
            let collectbd = cc.find("bowl/collectbd", this.node);
            if (collectbd) {
                collectbd.active = true;
                Global.SlotsSoundMgr.playEffect("sound_AZTEC_fire_boom");
                let script = collectbd.getComponent(cc.Animation);
                script.play();
                script.on("stop", ()=>{
                    script.off("stop");
                    collectbd.active = false;
                });
            }
        }


    },

    isPlaySymbolScatterAudio(colIdx) {
        let result = true;
        for (let i = 0; i <= colIdx; i++) {
            let reel = this._reels[i];
            if (!reel.hasScatter()) {
                result = false;
                break;
            }
        }
        return result;
    },

    /**
     * 更新激活的金色图标
     * @param betIndex 从1开始
     */
    updateActiveGoldSymbol(betIndex) {
        let deskInfo = cc.vv.gameData.getDeskInfo();
        for (let i = deskInfo.betLevelConfig.length - 1; i > 0; i--) {
            let node = cc.find("reels_frame/symbol_info/symbol_" + i, this.node);
            if (node) {
                if (betIndex >= deskInfo.betLevelConfig[i]) {
                    node.getComponent("ImgSwitchCmp").setIndex(0);
                } else {

                    node.getComponent("ImgSwitchCmp").setIndex(1);
                }
            }
        }
    },
});