/**
 * @description
 */
cc.Class({
    extends: require("LMSlots_Symbol_Base"),
    properties: {},

    playBonusSgAnimation() {
        let aniNode = cc.find("bonus_sg", this._showNode);
        if (aniNode) {
            Global.SlotsSoundMgr.playEffect("sound_AZTEC_wild_fire");
            aniNode.active = true;
            let script = aniNode.getComponent(cc.Animation);
            script.play();
            script.on("stop", () => {
                script.off("stop");
                aniNode.active = false;
            });
        }
    },

    playWinTweenAction(){
        this._showNode.stopAllActions()
        //记录原始缩放
        cc.tween(this._showNode)
            .repeatForever(cc.tween()
                .to(0.35,{opacity:0})
                .to(0.35,{opacity: 255})
                .delay(1)
            )
            .start()
    },
    //停止tween类型的action动画
    stopWinTweenAction(){
        if(this._showNode){
            this._showNode.active = true
            this._showNode.stopAllActions()

            this._showNode.opacity = 255
        }
    }
});