/**
 * @description
 */

let regularSymbols = [2, 8, 9, 11, 13];
let selectSymbols = [
    [4, 5, 6, 7],
    [4, 5, 6, 107],
    [4, 5, 106, 107],
    [4, 105, 106, 107],
    [104, 105, 106, 107]
];

cc.Class({
    extends: cc.Component,
    properties: {
        bg: cc.Node,
        tips: cc.Node,
        top_bg: cc.Node,
        select_node: cc.Node,
        select_animation: cc.Node,
        tips_bg: cc.Node,

        _curBetIndex: 0,
        _timer: 0,
        _polling: false,
        _canSelect: false,
    },

    init() {
        this.node.active = true;
        cc.vv.gameData.GetBottomScript().ShowBtnsByState("moveing_1");
        this.setSymbolInfo(4);
        this.open();
        let deskInfo = cc.vv.gameData.getDeskInfo();

        for (let i = 1; i < 6; i++) {
            let select = cc.find("select_" + i, this.select_node);
            if (select) {
                cc.find("bet", select).getComponent(cc.Label).string = "BET $" +
                    Global.formatNumShort(deskInfo.mults[deskInfo.betLevelConfig[i - 1] - 1], 0);
                select.off(cc.Node.EventType.TOUCH_END);
                select.on(cc.Node.EventType.TOUCH_END, async ()=>{
                    if (!this._canSelect) {
                        return;
                    }

                    this._polling = false;

                    Global.SlotsSoundMgr.playEffect("sound_AZTEC_click_bet");

                    this._canSelect = false;
                    this.setSymbolInfo(i - 1);
                    cc.vv.gameData.GetBottomScript().SetBetIdx(cc.vv.gameData.getDeskInfo().betLevelConfig[i - 1]);
                    for (let j = 1; j < 6; j++) {
                        let black = cc.find("select_" + j + "/black", this.select_node);
                        black.active = j !== i;
                    }

                    cc.tween(this.bg)
                        .to(0.5, {scale: 0}, {easing: "backIn"})
                        .call(()=>{
                            this.node.active = false;
                            cc.vv.gameData.GetSlotsScript().updateActiveGoldSymbol(
                                cc.vv.gameData.getDeskInfo().betLevelConfig[i - 1]
                            );
                            cc.vv.gameData.GetSlotsScript().CanDoNextRound();
                        })
                        .start();
                });
            }
        }
    },

    open() {
        this.node.active = true;
        this.reset();
        this.bg.scale = 0;

        Global.SlotsSoundMgr.playEffect("sound_AZTEC_choose_bet_window");
        cc.tween(this.bg)
            .to(0.5, {scale: 1}, {easing: "backOut"})
            .start();

        this.tips.active = true;
        this.tips_bg.scale = 0;
        cc.tween(this.tips_bg)
            .to(0.5, {scale: 1}, {easing: "backOut"})
            .delay(1)
            .to(0.5, {scale: 0}, {easing: "backIn"})
            .call(()=>{
                this.tips.active = false;
                this._polling = true;
                this._canSelect = true;
            })
            .start();
    },

    reset() {
        for (let j = 1; j < 6; j++) {
            let black = cc.find("select_" + j + "/black", this.select_node);
            black.active = false;
        }
    },

    update(dt) {
        if (this._polling) {
            this._timer += dt;
            if (this._timer >= 2) {
                this._timer = 0;
                this._curBetIndex--;
                if (this._curBetIndex < 0) {
                    this._curBetIndex = 4;
                }
                this.setSymbolInfo(this._curBetIndex);
            }
        }
    },

    setSymbolInfo(betIndex) {
        this._curBetIndex = betIndex;

        this.select_animation.y = cc.find("select_" + (betIndex + 1), this.select_node).y;

        let deskInfo = cc.vv.gameData.getDeskInfo();
        for (let i = 0; i < regularSymbols.length; i++) {
            let node = cc.find("node_" + regularSymbols[i], this.top_bg);
            if (node) {
                for (let j = 1; j < 4; j++) {
                    let coin = cc.find("coin_" + j, node);
                    if (coin) {
                        coin.getComponent(cc.Label).string = Global.formatNumShort(
                            deskInfo.cardConfig[regularSymbols[i]].mult[j + 1] * deskInfo.betLevelConfig[this._curBetIndex], 0);
                    }
                }
            }
        }

        for (let i = 4; i < 8; i++) {
            let node = cc.find("node_" + i, this.top_bg);
            if (node) {
                node.active = false;
            }
            node = cc.find("node_10" + i, this.top_bg);
            if (node) {
                node.active = false;
            }
        }

        for (let i = 0; i < selectSymbols[this._curBetIndex].length; i++) {
            let card = selectSymbols[this._curBetIndex][i];
            let node = cc.find("node_" + card, this.top_bg);
            if (node) {
                node.active = true;
                for (let j = 1; j < 4; j++) {
                    let coin = cc.find("coin_" + j, node);
                    if (coin) {
                        coin.getComponent(cc.Label).string = Global.formatNumShort(
                            deskInfo.cardConfig[card].mult[j + 1] * deskInfo.betLevelConfig[this._curBetIndex], 0);
                    }
                }
            }
        }
    },
});