/**
 * @description
 */

let JackpotGameSymbol = {
    None: 0,
    Mini: 1,
    Minor: 2,
    Major: 3,
    Mega: 4,
    Grand: 5,
    Gold: 6
};

let prizePoolName = ["Mini", "Minor", "Major", "Mega", "Grand"];

let liziColor = [
    [0, 85, 185],
    [120, 0, 235],
    [0, 210, 0],
    [249, 3, 211],
    [252, 0, 0],
];

cc.Class({
    extends: cc.Component,
    properties: {
        prizePool: cc.Node,
        result_bg: cc.Node,
        result_jackpot: cc.Node,
        winCoins: cc.Node,
        btn_collect: cc.Node,

        _successCallback: null,
        _canSelect: false,
        _haveOpenReward: null,
        _winCoin: 0,
    },

    onLoad() {
        this._haveOpenReward = [];
        for (let i = 1; i < 19; i++) {
            let coin_node = cc.find("node_" + i, this.node);
            coin_node.on(cc.Node.EventType.TOUCH_END, async ()=>{
                if (!this._canSelect) {
                    return;
                }

                if (this._haveOpenReward.indexOf(i) !== -1) {
                    return;
                }

                this._canSelect = false;

                Global.SlotsSoundMgr.playEffect("sound_AZTEC_click_coin");

                let req = {rtype:2, choiceId: i};
                let result = await cc.vv.gameData.reqSubGame(req);
                if (result.code === 200) {

                    let pickInfo = result.data.pickInfo;
                    let jackpotGame = result.data.jackpotGame;
                    this._haveOpenReward.push(pickInfo.choiceId);
                    if (pickInfo.symbol === JackpotGameSymbol.Gold) {
                        Global.SlotsSoundMgr.playEffect("sound_AZTEC_super_appear");
                        let node = cc.find("node_" + pickInfo.choiceId, this.node);
                        let jinbi = cc.find("jinbi", node);
                        cc.tween(jinbi)
                            .to(0.3, {scaleX: 0})
                            .start();

                        this.playAnimationOnce(cc.find("dianji", node));

                        await cc.vv.gameData.awaitTime(0.3);

                        let result = cc.find("gold_man", node);
                        result.active = true;
                        result.scaleX = 0;
                        cc.tween(result)
                            .to(0.3, {scaleX: 1})
                            .start();

                        let shine = cc.find("jinrenshine", node);
                        shine.active = true;
                        shine.scale = 0;
                        cc.tween(shine)
                            .to(0.3, {scale: 4})
                            .start();


                        await cc.vv.gameData.awaitTime(1);

                        this.removeSymbol(jackpotGame, pickInfo);
                    } else {
                        let node = cc.find("node_" + pickInfo.choiceId, this.node);
                        let jinbi = cc.find("jinbi", node);
                        cc.tween(jinbi)
                            .to(0.3, {scaleX: 0})
                            .start();

                        this.playAnimationOnce(cc.find("dianji", node));

                        await cc.vv.gameData.awaitTime(0.3);

                        let result = cc.find("result", node);
                        result.active = true;
                        result.scaleX = 0;
                        result.getComponent("ImgSwitchCmp").setIndex(pickInfo.symbol - 1);
                        cc.tween(result)
                            .to(0.3, {scaleX: 1})
                            .call(()=>{
                                // 点亮jackpot
                                cc.find("prizePool_" + prizePoolName[pickInfo.symbol - 1] + "/point_" +
                                    jackpotGame.jackpotCnt[pickInfo.symbol - 1] + "/reward", this.prizePool).active = true;

                            })
                            .start();

                        let dianjilizi = cc.find("dianjilizi", node);
                        dianjilizi.active = true;
                        let color = liziColor[pickInfo.symbol - 1];
                        dianjilizi.color = cc.color(color[0], color[1], color[2]);
                        this.playAnimationOnce(dianjilizi);

                        await cc.vv.gameData.awaitTime(1);

                        this._canSelect = true;
                    }

                    if (jackpotGame.isEnd) {
                        this._canSelect = false;
                        Global.SlotsSoundMgr.playEffect("sound_AZTEC_bonus_reward");
                        this.endGame(jackpotGame);
                    }
                }
            });
        }
    },

    async removeSymbol(jackpotGame, pickInfo) {
        for (let index of pickInfo.currRemoveIdxs) {
            let node = cc.find("node_" + index, this.node);
            let result = cc.find("result", node);
            if (this._haveOpenReward.indexOf(index) === -1) {
                this._haveOpenReward.push(index);
                let jinbi = cc.find("jinbi", node);
                jinbi.color = cc.Color.GRAY;
                cc.tween(jinbi)
                    .to(0.3, {scaleX: 0})
                    .start();

                result.active = true;
                result.color = cc.Color.GRAY;
                result.scaleX = 0;
                result.getComponent("ImgSwitchCmp").setIndex(jackpotGame.goldSymbolCnt - 1);
                cc.tween(result)
                    .delay(0.3)
                    .to(0.3, {scaleX: 1})
                    .start();
            } else {
                result.color = cc.Color.GRAY;
            }
        }

        await cc.vv.gameData.awaitTime(1);

        let startPos = cc.find("node_" + pickInfo.choiceId, this.node).convertToWorldSpaceAR(cc.v2(0, 0));
        startPos = this.node.parent.convertToNodeSpaceAR(startPos);
        Global.SlotsSoundMgr.playEffect("sound_AZTEC_super_line");
        let particle = cc.instantiate(cc.find("particle_fly", this.node.parent));
        particle.active = true;
        particle.parent = this.node.parent;
        particle.position = startPos;
        let removeJackpot = cc.find("prizePool_" + prizePoolName[jackpotGame.goldSymbolCnt - 1], this.prizePool)
        let endPos = removeJackpot.convertToWorldSpaceAR(cc.v2(0, 0));
        endPos = this.node.parent.convertToNodeSpaceAR(endPos);

        cc.tween(particle)
            .to(0.5, {position: endPos})
            .call(()=>{
                let jackpotBaodian = cc.find("jackpotbaodian", this.prizePool);
                jackpotBaodian.position = removeJackpot.position;
                this.playAnimationOnce(jackpotBaodian, null, ()=>{
                    for (let child of removeJackpot.children) {
                        child.color = cc.Color.GRAY;
                    }
                    for (let i = 1; i < 4; i++) {
                        cc.find("point_" + i + "/reward", removeJackpot).active = true;
                        cc.find("point_" + i + "/reward", removeJackpot).color = cc.Color.GRAY;
                    }

                    this._canSelect = true;
                });
            })
            .removeSelf()
            .start();
    },

    async endGame(jackpotGame) {
        for (let j = 1; j < 19; j++) {
            // 所有的翻过来
            let node = cc.find("node_" + j, this.node);
            let result = cc.find("result", node);
            if (jackpotGame.symbolInfos[j - 1] === JackpotGameSymbol.Gold) {
                result = cc.find("gold_man", node);
            }
            if (this._haveOpenReward.indexOf(j) === -1) {
                cc.tween(cc.find("jinbi", node))
                    .to(0.3, {scaleX: 0})
                    .start();
                result.active = true;
                result.scaleX = 0;
                if (jackpotGame.symbolInfos[j - 1] === JackpotGameSymbol.Gold) {
                    
                } else {
                    result.getComponent("ImgSwitchCmp").setIndex(jackpotGame.symbolInfos[j - 1] - 1);
                }

                cc.tween(result)
                    .delay(0.3)
                    .to(0.3, {scaleX: 1})
                    .start();
            }
            
            // 变黑
            if (jackpotGame.symbolInfos[j - 1] !== jackpotGame.jackpot.id) {
                result.color = cc.Color.GRAY;
            }
        }

        await cc.vv.gameData.awaitTime(1);

        Global.SlotsSoundMgr.playEffect("sound_AZTEC_show_jackpot");

        let free_dialog = cc.find("result_bg", this.node);
        free_dialog.active = true;

        let dialog = cc.find("bg", free_dialog);
        dialog.active = true;

        cc.tween(dialog)
            .to(0.5, {scale: 1}, {easing: "backOut"})
            .start()

        let coin = cc.find("coins", dialog);
        coin.getComponent(cc.Label).string = "";

        let jackpot = cc.find("jackpot", dialog);
        jackpot.getComponent("ImgSwitchCmp").setIndex(jackpotGame.jackpot.id - 1);

        let btn_collect = cc.find("btn_collect", dialog);
        Global.SlotsSoundMgr.playEffect("sound_AZTEC_jackpot_up");
        Global.doRoallNumEff(coin, 0, jackpotGame.jackpot.value, 6, ()=>{
            Global.SlotsSoundMgr.playEffect("sound_AZTEC_jackpot_end");
        }, null, 0, true);
        this._winCoin = jackpotGame.jackpot.value;

        await cc.vv.gameData.awaitTime(0.5);

        btn_collect.off("click");
        let func = async ()=>{
            btn_collect.off("click");
            coin.stopAllActions();
            Global.SlotsSoundMgr.stopEffectByName("sound_AZTEC_jackpot_up");
            coin.getComponent(cc.Label).string = Global.FormatNumToComma(jackpotGame.jackpot.value);
            Global.SlotsSoundMgr.playEffect("sound_AZTEC_jackpot_end");
            cc.tween(dialog)
                .to(0.5, {scale: 0}, {easing: "backIn"})
                .call(()=>{
                    dialog.active = false;
                    free_dialog.active = false;

                    if (this._successCallback) {
                        this._successCallback();
                        this._successCallback = null;
                    }
                })
                .start();
        }
        cc.vv.gameData.checkAutoPlay(btn_collect, func);
        btn_collect.on("click", async () => {
            btn_collect.stopAllActions();
            await func();
        });
    },

    playAnimationOnce(node, animationName, callback) {
        node.active = true;
        if (animationName) {
            node.getComponent(cc.Animation).play(animationName);
        } else {
            node.getComponent(cc.Animation).play();
        }

        node.getComponent(cc.Animation).on("stop", ()=>{
            node.getComponent(cc.Animation).off("stop");
            node.active = false;
            if (callback) {
                callback();
            }
        });
    },

    async reconnect(jackpotGame, success) {
        cc.vv.AudioManager.playBgm("games/BrilliantTreasures/", "bonus_bgm", true);
        this.reset();
        this._successCallback = success;
        this.node.active = true;
        let gameCfg = cc.vv.gameData.getGameCfg();

        this.prizePool.getComponent("LMSlots_PrizePool_Base").PausePool([
            {prizeType: 0, pauseNum: jackpotGame.jackpotValues[0]},
            {prizeType: 1, pauseNum: jackpotGame.jackpotValues[1]},
            {prizeType: 2, pauseNum: jackpotGame.jackpotValues[2]},
            {prizeType: 3, pauseNum: jackpotGame.jackpotValues[3]},
            {prizeType: 4, pauseNum: jackpotGame.jackpotValues[4]}
        ]);

        for (let i = 0; i < jackpotGame.symbolInfos.length; i++) {
            let coin_node = cc.find("node_" + (i + 1), this.node);
            if (coin_node && jackpotGame.symbolInfos[i] !== 0) {
                coin_node.getChildByName("jinbi").active = false;
                let result = cc.find("result", coin_node);
                if (jackpotGame.symbolInfos[i] === JackpotGameSymbol.Gold) {
                    result = cc.find("gold_man", coin_node)

                    let shine = cc.find("jinrenshine", coin_node);
                    shine.active = true;
                    shine.scale = 4;
                } else {
                    result.getComponent("ImgSwitchCmp").setIndex(jackpotGame.symbolInfos[i] - 1);
                }
                result.active = true;
                result.scaleX = 1;

                this._haveOpenReward.push(i + 1);
            }
        }

        for (let i = 0; i < jackpotGame.jackpotCnt.length; i++) {
            for (let j = 0; j < 3; j++) {
                let point = cc.find("prizePool_" + prizePoolName[i] + "/point_" + (j + 1) + "/reward", this.prizePool);
                if (point) {
                    point.active = false;
                }
            }
        }

        for (let i = 0; i < jackpotGame.jackpotCnt.length; i++) {
            let count = jackpotGame.jackpotCnt[i];
            for (let j = 0; j < count; j++) {
                let point = cc.find("prizePool_" + prizePoolName[i] + "/point_" + (j + 1) + "/reward", this.prizePool);
                if (point) {
                    point.active = true;
                }
            }
        }

        for (let index of jackpotGame.removeIdxs) {
            let node = cc.find("node_" + index, this.node);
            let result = cc.find("result", node);
            let jinbi = cc.find("jinbi", node);
            jinbi.active = false;
            result.active = true;
            result.color = cc.Color.GRAY;
            result.scaleX = 1;
            result.getComponent("ImgSwitchCmp").setIndex(jackpotGame.goldSymbolCnt - 1);
        }

        if (jackpotGame.goldSymbolCnt > 0) {
            let removeJackpot = cc.find("prizePool_" + prizePoolName[jackpotGame.goldSymbolCnt - 1], this.prizePool)
            for (let child of removeJackpot.children) {
                child.color = cc.Color.GRAY;
            }
            for (let i = 1; i < 4; i++) {
                cc.find("point_" + i + "/reward", removeJackpot).active = true;
                cc.find("point_" + i + "/reward", removeJackpot).color = cc.Color.GRAY;
            }
        }


        this._canSelect = true;
    },

    startGame(success, jackpotGame) {
        this.node.active = true;
        this.reset();
        this._successCallback = success;
        this.prizePool.getComponent("LMSlots_PrizePool_Base").PausePool([
            {prizeType: 0, pauseNum: jackpotGame.jackpotValues[0]},
            {prizeType: 1, pauseNum: jackpotGame.jackpotValues[1]},
            {prizeType: 2, pauseNum: jackpotGame.jackpotValues[2]},
            {prizeType: 3, pauseNum: jackpotGame.jackpotValues[3]},
            {prizeType: 4, pauseNum: jackpotGame.jackpotValues[4]}
        ]);
        this._canSelect = true;
    },

    exitGame() {
        this.node.active = false;
    },

    getWinCoin() {
        return this._winCoin;
    },

    reset() {
        // 重置所有金币节点
        for (let i = 1; i < 19; i++) {
            let coin_node = cc.find("node_" + i, this.node);
            coin_node.getChildByName("jinbi").active = true;
            coin_node.getChildByName("jinbi").scaleX = 1;
            coin_node.getChildByName("jinbi").color = cc.Color.WHITE;
            coin_node.getChildByName("gold_man").active = false;
            coin_node.getChildByName("result").active = false;
            coin_node.getChildByName("gold_man").color = cc.Color.WHITE;
            coin_node.getChildByName("result").color = cc.Color.WHITE;
            coin_node.getChildByName("dianji").active = false;
            coin_node.getChildByName("dianjilizi").active = false;
            coin_node.getChildByName("jinrenshine").active = false;
        }

        for (let child of this.prizePool.children) {
            for (let i = 1; i < 4; i++) {
                let point = cc.find("point_" + i, child);
                if (point) {
                    cc.find("reward", point).active = false;
                    cc.find("reward", point).color = cc.Color.WHITE;
                }
            }
            for (let childElement of child.children) {
                childElement.color = cc.Color.WHITE;

            }

        }

        // 重置结算界面
        this.result_bg.active = false;

        // 重置变量
        this._successCallback = null;
        this._canSelect = false;
        this._haveOpenReward = [];
        this._winCoin = 0;
    },
});